import{_ as a}from"./chunks/placeholder.CpMbP-ia.js";import{_ as n,o as p,a as l,b as c}from"./app.C41L12d5.js";const w=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"guide/operator_practice/typical_operator_cases/simd_operator_impl/add_vector_operator/intermediate_optimization.md","filePath":"guide/operator_practice/typical_operator_cases/simd_operator_impl/add_vector_operator/intermediate_optimization.md","outlineHeaders":[{"level":2,"title":"性能瓶颈分析","slug":"性能瓶颈分析","link":"#性能瓶颈分析"},{"level":2,"title":"优化手段解析与实施","slug":"优化手段解析与实施","link":"#优化手段解析与实施"},{"level":3,"title":"优化策略1：标量→向量指令","slug":"优化策略1：标量→向量指令","link":"#优化策略1：标量→向量指令"},{"level":3,"title":"优化策略2：多核均匀切分 + 大块搬运","slug":"优化策略2：多核均匀切分-+-大块搬运","link":"#优化策略2：多核均匀切分-+-大块搬运"},{"level":3,"title":"优化策略3：双缓冲流水线并行","slug":"优化策略3：双缓冲流水线并行","link":"#优化策略3：双缓冲流水线并行"},{"level":2,"title":"优化效果评估","slug":"优化效果评估","link":"#优化效果评估"}],"lastUpdated":1787050286000}'),t={name:"guide/operator_practice/typical_operator_cases/simd_operator_impl/add_vector_operator/intermediate_optimization.md"};function e(o,s,i,r,d,g){return p(),l("div",null,[...s[0]||(s[0]=[c(`<div><article class="markdown-body"><h1>中级性能优化<span id="ZH-CN_TOPIC_000000_ADD_MID"></span></h1><p>本节在入门功能落地的基础上，介绍Add算子的中级性能优化方法。</p><h2 id="性能瓶颈分析">性能瓶颈分析<a class="header-anchor" href="#性能瓶颈分析">​</a></h2><p>基于入门级代码的Profiling数据（以<a href="https://gitcode.com/cann/asc-devkit/blob/master/examples/01_simd_cpp_api/05_best_practices/00_vector_compute/add_high_performance/README.md#case-0-%E5%8D%95%E6%A0%B8%E6%A0%87%E9%87%8F%E7%89%88%E6%9C%AC%E5%9F%BA%E5%87%86%E7%A8%8B%E5%BA%8F">8192×8192 half</a>为基准），核心性能瓶颈如下：</p><blockquote><p><strong>说明</strong>：入门功能落地版使用float数据类型是为了简化理解；从中级性能优化版起切换至half数据类型，以获得更高的向量计算性能和搬运效率。以下Profiling数据及优化效果均基于half类型测试。</p></blockquote><table><thead><tr><th align="left">指标</th><th align="center">Case 0（标量基准）</th><th align="center">Case 1（单核向量）</th><th align="center">Case 2（多核切分）</th></tr></thead><tbody><tr><td align="left">Task Duration(μs)</td><td align="center">1239689.1</td><td align="center">6909.6</td><td align="center">306.58</td></tr><tr><td align="left">aiv_vec_ratio</td><td align="center">0</td><td align="center">0.11</td><td align="center">0.053</td></tr><tr><td align="left">aiv_scalar_ratio</td><td align="center">0.995</td><td align="center">0.033</td><td align="center">0.028</td></tr><tr><td align="left">aiv_mte2_ratio</td><td align="center">0.005</td><td align="center">0.873</td><td align="center">0.725</td></tr><tr><td align="left">aiv_mte3_ratio</td><td align="center">0.002</td><td align="center">0.378</td><td align="center">0.183</td></tr></tbody></table><p><strong>核心瓶颈解读</strong>：</p><ul><li><strong>痛点1：标量运算瓶颈</strong>（Case 0）：标量指令耗时占比99.5%，逐元素串行执行，无法利用硬件并行能力。</li><li><strong>痛点2：数据搬运瓶颈</strong>（Case 1）：单核向量版本中MTE2占比87.3%，数据搬运成为主要瓶颈，单核搬运请求量不足导致带宽未用满。</li><li><strong>痛点3：搬运粒度小</strong>（Case 2）：多核切分后MTE2占比72.5%，小块搬运（8KB）未充分利用带宽。</li></ul><h2 id="优化手段解析与实施">优化手段解析与实施<a class="header-anchor" href="#优化手段解析与实施">​</a></h2><h3 id="优化策略1：标量→向量指令">优化策略1：标量→向量指令<a class="header-anchor" href="#优化策略1：标量→向量指令">​</a></h3><p><strong>原理解析</strong>：标量运算每次只能处理1个数据元素，需要逐元素循环；向量指令（如<a href="../../../../../api/SIMD-API/basic_api/memory_vector_compute/basic_arithmetic/Add.html">AscendC::Add</a>）单次可处理多个数据元素，利用向量单元的并行计算能力，可获得百倍以上性能提升。</p><p><strong>代码改造点</strong>：将<code>for</code>循环配合<code>GetValue/SetValue</code>的标量运算替换为向量API：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// 标量方式（Case 0）</span>
<span class="k">for</span><span class="w"> </span><span class="p">(</span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="n">curLen</span><span class="p">;</span><span class="w"> </span><span class="n">i</span><span class="o">++</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">    </span><span class="kt">float</span><span class="w"> </span><span class="n">xVal</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="p">(</span><span class="kt">float</span><span class="p">)</span><span class="n">xLocal</span><span class="p">.</span><span class="n">GetValue</span><span class="p">(</span><span class="n">i</span><span class="p">);</span>
<span class="w">    </span><span class="kt">float</span><span class="w"> </span><span class="n">yVal</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="p">(</span><span class="kt">float</span><span class="p">)</span><span class="n">yLocal</span><span class="p">.</span><span class="n">GetValue</span><span class="p">(</span><span class="n">i</span><span class="p">);</span>
<span class="w">    </span><span class="n">zLocal</span><span class="p">.</span><span class="n">SetValue</span><span class="p">(</span><span class="n">i</span><span class="p">,</span><span class="w"> </span><span class="p">(</span><span class="n">half</span><span class="p">)(</span><span class="n">xVal</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">yVal</span><span class="p">));</span>
<span class="p">}</span>

<span class="c1">// 向量方式（Case 1）</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">Add</span><span class="p">(</span><span class="n">zLocal</span><span class="p">,</span><span class="w"> </span><span class="n">xLocal</span><span class="p">,</span><span class="w"> </span><span class="n">yLocal</span><span class="p">,</span><span class="w"> </span><span class="n">curLen</span><span class="p">);</span>
</code></pre></div><p>性能提升：端到端耗时从1239689.1μs降至6909.6μs，提升<strong>99.4%</strong>。</p><h3 id="优化策略2：多核均匀切分-+-大块搬运">优化策略2：多核均匀切分 + 大块搬运<a class="header-anchor" href="#优化策略2：多核均匀切分-+-大块搬运">​</a></h3><p><strong>原理解析</strong>：</p><ul><li><strong>多核并行</strong>：将数据均匀切分到多个AIV Core，实现并行计算。使用均匀切分策略（余数分配到前几个核），确保负载均衡。</li><li><strong>大块搬运</strong>：在Unified Buffer（UB）空间允许范围内增大<code>dataCopyLen</code>，减少搬运次数，摊薄启动开销，更好地利用内存带宽。</li></ul><p><strong>代码改造点</strong>：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// 均匀切分：计算每个核处理的行数</span>
<span class="kt">uint32_t</span><span class="w"> </span><span class="n">baseCoreM</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">totalM</span><span class="w"> </span><span class="o">/</span><span class="w"> </span><span class="n">splitM</span><span class="p">;</span>
<span class="kt">uint32_t</span><span class="w"> </span><span class="n">remainderM</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">totalM</span><span class="w"> </span><span class="o">%</span><span class="w"> </span><span class="n">splitM</span><span class="p">;</span>
<span class="k">if</span><span class="w"> </span><span class="p">(</span><span class="n">blockIdxM</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="n">remainderM</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">    </span><span class="n">actualCoreM</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">baseCoreM</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="mi">1</span><span class="p">;</span><span class="w">  </span><span class="c1">// 均匀分配余数</span>
<span class="p">}</span>

<span class="c1">// 增大搬运粒度：dataCopyLen从4096提升至16384（Case 2→Case 3）</span>
</code></pre></div><p>性能提升：Case 2→Case 3，端到端耗时从306.58μs降至268.5μs，减少<strong>12.5%</strong>。</p><h3 id="优化策略3：双缓冲流水线并行">优化策略3：双缓冲流水线并行<a class="header-anchor" href="#优化策略3：双缓冲流水线并行">​</a></h3><p><strong>原理解析</strong>：采用Ping-Pong双缓冲技术，Ping缓冲区进行计算时，Pong缓冲区进行数据搬运，交替执行实现计算与搬运的流水线并行。</p><img src="`+a+`" width="50%"><p><strong>代码改造点</strong>：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// Ping-Pong双缓冲地址分配</span>
<span class="k">static</span><span class="w"> </span><span class="k">constexpr</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">xAddrPing</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span>
<span class="k">static</span><span class="w"> </span><span class="k">constexpr</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">yAddrPing</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">MAX_DATA_COPY_LEN</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="n">half</span><span class="p">);</span>
<span class="k">static</span><span class="w"> </span><span class="k">constexpr</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">zAddrPing</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">yAddrPing</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">MAX_DATA_COPY_LEN</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="n">half</span><span class="p">);</span>
<span class="k">static</span><span class="w"> </span><span class="k">constexpr</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">xAddrPong</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">zAddrPing</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">MAX_DATA_COPY_LEN</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="n">half</span><span class="p">);</span>
<span class="c1">// ...</span>

<span class="c1">// 双缓冲流水线：交替使用两组缓冲区</span>
<span class="k">for</span><span class="w"> </span><span class="p">(</span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">loopIdx</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span><span class="w"> </span><span class="n">loopIdx</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="n">totalBlocks</span><span class="p">;</span><span class="w"> </span><span class="n">loopIdx</span><span class="o">++</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">    </span><span class="kt">int32_t</span><span class="w"> </span><span class="n">eventID</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="p">(</span><span class="n">loopIdx</span><span class="w"> </span><span class="o">%</span><span class="w"> </span><span class="mi">2</span><span class="w"> </span><span class="o">==</span><span class="w"> </span><span class="mi">0</span><span class="w"> </span><span class="o">?</span><span class="w"> </span><span class="n">EVENT_ID0</span><span class="w"> </span><span class="o">:</span><span class="w"> </span><span class="n">EVENT_ID1</span><span class="p">);</span>
<span class="w">    </span><span class="c1">// ... 数据搬运和计算，使用对应的eventID同步</span>
<span class="p">}</span>
</code></pre></div><p>性能提升：Case 3→Case 4，端到端耗时从268.5μs降至264.02μs，减少<strong>1.7%</strong>。双缓冲的收益有限，说明瓶颈在搬运速度本身。</p><h2 id="优化效果评估">优化效果评估<a class="header-anchor" href="#优化效果评估">​</a></h2><table><thead><tr><th align="left">指标</th><th align="center">Case 0（入门基准）</th><th align="center">Case 4（中级优化版）</th><th align="center">提升幅度</th></tr></thead><tbody><tr><td align="left">Task Duration(μs)</td><td align="center">1239689.1</td><td align="center">264.02</td><td align="center"><strong>4695倍</strong></td></tr><tr><td align="left">aiv_vec_time(μs)</td><td align="center">0.015</td><td align="center">12.846</td><td align="center">-</td></tr><tr><td align="left">aiv_scalar_time(μs)</td><td align="center">1233742.494</td><td align="center">2.796</td><td align="center"><strong>99.8%</strong></td></tr><tr><td align="left">aiv_mte2_ratio</td><td align="center">0.005</td><td align="center">0.973</td><td align="center">MTE2利用率大幅提升</td></tr></tbody></table><p><strong>本阶段结论</strong>：经过标量→向量、多核切分、大块搬运、双缓冲四级优化，端到端性能从1.24秒降至264μs，提升4695倍。当前瓶颈在于搬运速度本身，MTE2利用率已达97.3%，进一步优化需要从L2 Cache和UB内存布局入手。</p><p>详细内容请参见<a href="https://gitcode.com/cann/asc-devkit/blob/master/examples/01_simd_cpp_api/05_best_practices/00_vector_compute/add_high_performance/README.md#%E4%B8%AD%E7%BA%A7%E6%80%A7%E8%83%BD%E4%BC%98%E5%8C%96">Add性能调优样例 Case 1-4</a>。</p></article></div>`,1)])])}const v=n(t,[["render",e]]);export{w as __pageData,v as default};
